package com.wizzadrds.theworldremembers.dream; import com.wizzadrds.theworldremembers.memory.*; import com.wizzadrds.theworldremembers.stress.NpcStressManager; import net.minecraft.server.level.ServerLevel; import java.util.*; public final class DreamGenerator { public Dream generate(UUID npc,long sleepEpoch,MemoryManager memories,NpcStressManager stress){var list=memories.memoriesOf(npc);int s=stress.value(npc);long seed=npc.getMostSignificantBits()^npc.getLeastSignificantBits()^sleepEpoch;var rng=new Random(seed);DreamType type;if(s>=70)type=DreamType.FEAR;else if(list.stream().anyMatch(m->m.type()==MemoryEventType.NPC_FAMILY_LOST||m.type()==MemoryEventType.NPC_DIED)&&rng.nextInt(100)<55)type=DreamType.NOSTALGIA;else if(!list.isEmpty()&&rng.nextInt(100)<75)type=DreamType.MEMORY;else type=DreamType.IMPOSSIBLE;String text=switch(type){case MEMORY->"A memory returns, changed by sleep.";case FEAR->"A known danger follows through the dark.";case NOSTALGIA->"A familiar home and familiar voices feel close again.";case IMPOSSIBLE->"The remembered world bends into something impossible.";};return new Dream(npc,type,sleepEpoch,text,false);}}
